    if (linear_init(&model->enc_v2_gru2_input, arrays, "enc_v2_gru2_input_bias", "enc_v2_gru2_input_subias", "enc_v2_gru2_input_weights_int8","enc_v2_gru2_input_weights_float", "enc_v2_gru2_input_weights_idx", NULL, "enc_v2_gru2_input_scale", 224, 192)) return 1;
